from taf.gnb.oam.coam.vdu.utilities.http_client import HttpClient


class EMServiceLicensedv1HttpClient(HttpClient):
    """ This class provides a client for the EM Service Licensed V1 API. """

    def __init__(self, base_url, connection_alias):
        super(EMServiceLicensedv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/licensed/v1"

    def get_activated_operation_detail_status(self, plan_id, operation_id, timeout=30):
        endpoint = f'/plans/{plan_id}/operations/activations/{operation_id}/results'
        headers = {
          "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, headers=headers, timeout=timeout)
